pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EtherLotto} from "../src/EtherLotto.sol";

contract InvMutTest is Test {
    EtherLotto c;
    function setUp() public { c = new EtherLotto(); }

    function testFuzz_property(address caller, uint256 sent) public {
        vm.assume(caller != address(0));
        sent = bound(sent, 0, 1 ether);

        vm.deal(caller, sent);
        bool ok;
        vm.prank(caller);
        try c.play{value: sent}() {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(!ok || sent == 10);
    }
}
